-- Trophy thresholds per species: from what weight / length a catch counts as a trophy.
-- Approximate values from IGFA all-tackle records and FishBase max sizes plus Costa Rican
-- charter references; there is no official standard. Null thresholds = not a trophy species.
alter table public.species
  add column if not exists trophy_weight_kg numeric(6,1),
  add column if not exists trophy_length_cm numeric(5,0),
  add column if not exists trophy_note_es text,
  add column if not exists trophy_note_en text,
  add column if not exists trophy_source_url text;

update public.species s
set trophy_weight_kg = v.w, trophy_length_cm = v.l,
    trophy_note_es = v.es, trophy_note_en = v.en, trophy_source_url = v.src
from (values
  ('Parachromis dovii', 3::numeric, 55::numeric, 'Un guapote de más de 3 kg (unos 55 cm de largo total) es un trofeo; el récord es de pocos kilos.', 'A rainbow bass over 3 kg (about 55 cm total length) is a trophy; the species tops out at a few kg.', 'https://www.fishbase.de/summary/Parachromis-dovii.html'),
  ('Brycon guatemalensis', 2::numeric, 50::numeric, 'Una machaca de más de 2 kg (unos 50 cm) es grande; hay pocos datos, es un valor aproximado.', 'A machaca over 2 kg (about 50 cm) is large; data is scarce, so this is a rough estimate.', 'https://www.fishbase.de/summary/Brycon-guatemalensis.html'),
  ('Centropomus undecimalis', 11::numeric, 100::numeric, 'Un róbalo de más de 11 kg (25 lb, cerca de 1 m de largo total) es un trofeo; el récord IGFA es de 24 kg.', 'A snook over 11 kg (25 lb, about 1 m total length) is a trophy; the IGFA record is 24 kg.', 'https://igfa.org/world-records-search/'),
  ('Megalops atlanticus', 45::numeric, 190::numeric, 'Un sábalo de más de 45 kg (100 libras, unos 1,9 m) es un trofeo; el récord IGFA es de 128 kg.', 'A tarpon over 45 kg (100 lb, about 1.9 m total length) is the classic trophy mark; IGFA record is 128 kg.', 'https://igfa.org/world-records-search/'),
  ('Lutjanus campechanus', 9::numeric, 75::numeric, 'Un pargo rojo de más de 9 kg (20 lb, unos 75 cm) es un trofeo; es raro en Costa Rica y el dato viene del Golfo.', 'A red snapper over 9 kg (20 lb, about 75 cm) is a trophy; the figure comes from the Gulf, as the species is uncommon in Costa Rica.', 'https://www.fishbase.de/summary/Lutjanus-campechanus.html'),
  ('Lutjanus guttatus', 4::numeric, 60::numeric, 'Un pargo manchado de más de 4 kg (unos 60 cm) es excepcional; es una especie mediana y hay pocos datos.', 'A spotted snapper over 4 kg (about 60 cm) is exceptional; it is a mid-size species and data is thin.', 'https://www.fishbase.de/summary/Lutjanus-guttatus.html'),
  ('Coryphaena hippurus', 18::numeric, 130::numeric, 'Un dorado de más de 18 kg (40 lb, unos 1,3 m de longitud a la horquilla) es un toro trofeo; el récord es de 40 kg.', 'A mahi-mahi over 18 kg (40 lb, about 1.3 m fork length) is a trophy bull; the all-tackle record is 40 kg.', 'https://igfa.org/world-records-search/'),
  ('Makaira nigricans', 227::numeric, null::numeric, 'Un marlín azul de más de 227 kg (500 lb) es un trofeo en el Pacífico de Costa Rica; los de 450 kg (1000 lb) son excepcionales.', 'A blue marlin over 227 kg (500 lb) is a trophy in Pacific Costa Rica; ''granders'' (450 kg) are exceptional.', 'https://igfa.org/world-records-search/'),
  ('Kajikia audax', 90::numeric, null::numeric, 'Un marlín rayado de más de 90 kg (200 lb) es un trofeo; el promedio en Costa Rica es bastante menor.', 'A striped marlin over 90 kg (200 lb) is a trophy; the typical Costa Rican catch is much smaller.', 'https://igfa.org/world-records-search/'),
  ('Istiophorus platypterus', 45::numeric, 270::numeric, 'Un pez vela de más de 45 kg (unos 2,7 m) es un trofeo en el Pacífico de Costa Rica; el promedio ronda 35-40 kg.', 'A sailfish over 45 kg (about 2.7 m total length) is a trophy in Pacific Costa Rica; typical fish are lighter.', 'https://igfa.org/world-records-search/'),
  ('Acanthocybium solandri', 25::numeric, 160::numeric, 'Un wahoo de más de 25 kg (55 lb, unos 1,6 m a la horquilla) es un trofeo; el récord IGFA es de 83 kg.', 'A wahoo over 25 kg (55 lb, about 1.6 m fork length) is a trophy; the IGFA record is 83 kg.', 'https://www.fishbase.de/summary/Acanthocybium-solandri.html'),
  ('Thunnus albacares', 45::numeric, 140::numeric, 'Un atún aleta amarilla de más de 45 kg (100 lb, unos 1,4 m a la horquilla) es un trofeo; los mayores pasan de 90 kg.', 'A yellowfin over 45 kg (100 lb, about 1.4 m fork length) is the usual ''cow'' tuna mark; the biggest exceed 90 kg.', 'https://igfa.org/world-records-search/'),
  ('Cynoscion squamipinnis', 5::numeric, 70::numeric, 'Una corvina aguada de más de 5 kg (unos 70 cm) es grande; hay pocos datos y el valor es aproximado.', 'A corvina over 5 kg (about 70 cm) is large; evidence is thin, so this is a rough value.', 'https://www.fishbase.de/summary/Cynoscion-squamipinnis.html'),
  ('Caranx hippos', 10::numeric, 85::numeric, 'Un jurel de más de 10 kg (22 lb, unos 85 cm a la horquilla) es un trofeo; el récord IGFA es de 25 kg.', 'A jack crevalle over 10 kg (22 lb, about 85 cm fork length) is a trophy; the IGFA record is 25 kg.', 'https://www.fishbase.de/summary/Caranx-hippos.html'),
  ('Trachinotus falcatus', 14::numeric, 90::numeric, 'Una palometa de más de 14 kg (30 lb, unos 90 cm) es un trofeo; el récord IGFA es de 23 kg.', 'A permit over 14 kg (30 lb, about 90 cm fork length) is a trophy; the IGFA record is 23 kg.', 'https://www.fishbase.de/summary/Trachinotus-falcatus.html'),
  ('Lutjanus cyanopterus', 25::numeric, 110::numeric, 'Una cubera de más de 25 kg (55 lb, cerca de 1,1 m) es un trofeo; el récord del Pacífico es de 36 kg.', 'A cubera snapper over 25 kg (55 lb, about 1.1 m) is a trophy; the Pacific all-tackle record is 36 kg.', 'https://igfa.org/world-records-search/'),
  ('Scomberomorus maculatus', 3::numeric, 65::numeric, 'Una sierra de más de 3 kg (unos 65 cm a la horquilla) es un trofeo; el récord IGFA es de unos 6 kg.', 'A Spanish mackerel over 3 kg (about 65 cm fork length) is a trophy; the IGFA record is about 6 kg.', 'https://www.fishbase.de/summary/Scomberomorus-maculatus.html'),
  ('Sphyraena barracuda', 14::numeric, 130::numeric, 'Una barracuda de más de 14 kg (30 lb, unos 1,3 m) es un trofeo; el récord IGFA es de 39 kg.', 'A barracuda over 14 kg (30 lb, about 1.3 m total length) is a trophy; the IGFA record is 39 kg.', 'https://www.fishbase.de/summary/Sphyraena-barracuda.html'),
  ('Epinephelus quinquefasciatus', 10::numeric, 80::numeric, 'Un mero de más de 10 kg (unos 80 cm) es un buen ejemplar; hay muy pocos datos, el valor es aproximado.', 'A grouper over 10 kg (about 80 cm) is a good fish; very little data exists, so this is a rough value.', 'https://www.fishbase.de/summary/Epinephelus-quinquefasciatus.html'),
  ('Carcharhinus leucas', 100::numeric, 230::numeric, 'Un tiburón toro de más de 100 kg (unos 2,3 m) es un ejemplar excepcional; se recomienda devolverlo al agua.', 'A bull shark over 100 kg (about 2.3 m) is exceptional; release is recommended.', 'https://www.fishbase.de/summary/Carcharhinus-leucas.html'),
  ('Gerres cinereus', null::numeric, null::numeric, 'No se considera pez trofeo; es un pez pequeño que se pesca como carnada o por diversión.', 'Not considered a trophy fish; it is a small species caught for bait or fun.', 'https://www.fishbase.de/summary/Gerres-cinereus.html'),
  ('Joturus pichardi', 2::numeric, 50::numeric, 'Un bobo de más de 2 kg (unos 50 cm) es excepcional; es un pez difícil de pescar y hay pocos datos.', 'A mountain mullet over 2 kg (about 50 cm) is exceptional; it is hard to catch and data is thin.', 'https://www.fishbase.de/summary/Joturus-pichardi.html'),
  ('Oreochromis niloticus', 2.5::numeric, 45::numeric, 'Una tilapia de más de 2,5 kg (unos 45 cm) es grande; el récord IGFA es de unos 4 kg.', 'A tilapia over 2.5 kg (about 45 cm) is large; the IGFA record is about 4 kg.', 'https://www.fishbase.de/summary/Oreochromis-niloticus.html'),
  ('Rhamdia guatemalensis', 1::numeric, 40::numeric, 'Un barbudo de más de 1 kg (unos 40 cm) es grande; hay pocos datos y el valor es aproximado.', 'A catfish over 1 kg (about 40 cm) is large; data is scarce, so this is a rough value.', 'https://www.fishbase.de/summary/Rhamdia-guatemalensis.html'),
  ('Agonostomus monticola', null::numeric, null::numeric, 'No se considera pez trofeo; es una lisa pequeña de río (menos de 30 cm) sin pesca deportiva dirigida.', 'Not considered a trophy fish; it is a small river mullet (under 30 cm) with no targeted sport fishery.', 'https://www.fishbase.de/summary/Agonostomus-monticola.html'),
  ('Mayaheros urophthalmus', 0.8::numeric, 30::numeric, 'Una vieja de más de 0,8 kg (unos 30 cm) es grande para la especie; hay pocos datos.', 'A Mayan cichlid over 0.8 kg (about 30 cm) is big for the species; data is thin.', 'https://www.fishbase.de/summary/Mayaheros-urophthalmus.html'),
  ('Atractosteus tropicus', 5::numeric, 100::numeric, 'Un gaspar de más de 5 kg (cerca de 1 m) es un buen ejemplar; llega a más de 1,2 m, pero hay pocos datos.', 'A tropical gar over 5 kg (about 1 m) is a good fish; it can exceed 1.2 m, but data is thin.', 'https://www.fishbase.de/summary/Atractosteus-tropicus.html'),
  ('Haemulon plumierii', 1.5::numeric, 40::numeric, 'Un roncador de más de 1,5 kg (unos 40 cm) es grande; la especie rara vez pasa de 50 cm.', 'A grunt over 1.5 kg (about 40 cm) is large; the species rarely exceeds 50 cm.', 'https://www.fishbase.de/summary/Haemulon-plumierii.html'),
  ('Nematistius pectoralis', 23::numeric, 130::numeric, 'Un pez gallo de más de 23 kg (50 lb, unos 1,3 m) es un trofeo en Costa Rica; el récord IGFA es de 52 kg.', 'A roosterfish over 23 kg (50 lb, about 1.3 m) is a trophy in Costa Rica; the IGFA record is about 52 kg.', 'https://www.fishbase.de/summary/Nematistius-pectoralis.html'),
  ('Mugil cephalus', null::numeric, null::numeric, 'No se considera pez trofeo; es una lisa que casi no se pesca de forma deportiva.', 'Not considered a trophy fish; mullet are rarely targeted for sport.', 'https://www.fishbase.de/summary/Mugil-cephalus.html'),
  ('Strongylura notata', null::numeric, null::numeric, 'No se considera pez trofeo; es un pez aguja pequeño que se usa de carnada o se pesca por diversión.', 'Not considered a trophy fish; a small needlefish caught for bait or fun.', 'https://www.fishbase.de/summary/Strongylura-notata.html'),
  ('Caranx crysos', 2.5::numeric, 50::numeric, 'Una cojinuda de más de 2,5 kg (unos 50 cm a la horquilla) es excepcional; casi siempre son más pequeñas.', 'A blue runner over 2.5 kg (about 50 cm fork length) is exceptional; most are far smaller.', 'https://www.fishbase.de/summary/Caranx-crysos.html'),
  ('Xiphias gladius', 136::numeric, null::numeric, 'Un pez espada de más de 136 kg (300 lb) es un trofeo; el récord IGFA pasa de 500 kg.', 'A swordfish over 136 kg (300 lb) is a trophy; the IGFA record exceeds 500 kg.', 'https://igfa.org/world-records-search/'),
  ('Rachycentron canadum', 18::numeric, 115::numeric, 'Una cobia de más de 18 kg (40 lb, unos 1,15 m) es un trofeo; el récord IGFA es de 61 kg.', 'A cobia over 18 kg (40 lb, about 1.15 m fork length) is a trophy; the IGFA record is 61 kg.', 'https://www.fishbase.de/summary/Rachycentron-canadum.html'),
  ('Trachinotus carolinus', 1.5::numeric, 40::numeric, 'Un pámpano de más de 1,5 kg (unos 40 cm) es un trofeo; la especie ronda 0,5 kg y pocas veces pasa de 3 kg.', 'A pompano over 1.5 kg (about 40 cm) is a trophy; typical fish are about 0.5 kg and rarely exceed 3 kg.', 'https://www.fishbase.de/summary/Trachinotus-carolinus.html'),
  ('Epinephelus labriformis', 1.5::numeric, 45::numeric, 'Una cabrilla de más de 1,5 kg (unos 45 cm) es un buen ejemplar; es una especie pequeña con pocos datos.', 'A cabrilla over 1.5 kg (about 45 cm) is a good fish; it is a small species with little data.', 'https://www.fishbase.de/summary/Epinephelus-labriformis.html'),
  ('Dasyatis americana', null::numeric, null::numeric, 'No se considera pez trofeo; casi no hay pesca deportiva dirigida y conviene soltarla con cuidado.', 'Not considered a trophy fish; there is no real targeted sport fishery and it should be released carefully.', 'https://www.fishbase.de/summary/Dasyatis-americana.html'),
  ('Sardinella aurita', null::numeric, null::numeric, 'No se considera pez trofeo; es un pez forrajero pequeño que se usa de carnada.', 'Not considered a trophy fish; it is a small forage fish used as bait.', 'https://www.fishbase.de/summary/Sardinella-aurita.html'),
  ('Oncorhynchus mykiss', 3::numeric, 55::numeric, 'Una trucha arcoíris de más de 3 kg (unos 55 cm) es un trofeo en Costa Rica, donde casi todas son más pequeñas.', 'A rainbow trout over 3 kg (about 55 cm) is a trophy in Costa Rica, where most are smaller.', 'https://www.fishbase.de/summary/Oncorhynchus-mykiss.html'),
  ('Poecilia gillii', null::numeric, null::numeric, 'No se considera pez trofeo; es un pez diminuto de unos pocos centímetros.', 'Not considered a trophy fish; it is a tiny fish a few centimeters long.', 'https://www.fishbase.de/summary/Poecilia-gillii.html')
) as v(sci, w, l, es, en, src)
where s.scientific_name = v.sci;
